/**
 * A colour field: a swatch, a hex entry and a picker popover (`design/components/color-input.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/color-input.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createUniqueId, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import * as zag from '@zag-js/color-picker'
import { normalizeProps } from '@zag-js/solid'

import {
  BORROWED,
  COLOR_INPUT_REST,
  IDENTITY,
  agentMember,
  claimSlot,
  composingKey,
  createCell,
  createDerived,
  elementRef,
  mergeParts,
  provide,
  scope,
  useDirection,
  useMachine,
  type BorrowedHolder,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/controls/color-input.module.css'
import a11y from '@polymorph/recipes/conventions/a11y.module.css'
import Input from './Input'
import Popover from '../overlays/Popover'

export interface ColorInputProps {
  /**
   * Enables the alpha channel: the alpha rail, the eight-digit hex and the checker.
   */
  alpha?: boolean
  'aria-describedby'?: string
  /**
   * Set by FormField. Set it directly only when there is no visible label.
   */
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-required'?: boolean
  /**
   * Opens the picker on mount, for galleries and tests. Screens let the user open it.
   */
  defaultOpen?: boolean
  defaultValue?: string
  disabled?: boolean
  id?: string
  invalid?: boolean
  /**
   * Serializes the hex through a hidden input.
   */
  name?: string
  /**
   * Fires continuously while dragging, as Input does, with no separate commit as on Slider.
   */
  onChange?: (value: string) => void
  /**
   * Names the swatch button and the popover, for example "Choose accent colour".
   */
  pickerLabel: string
  size?: 'sm' | 'md' | 'lg'
  /**
   * Lowercase hex: `#rrggbb`, or `#rrggbbaa` with `alpha`.
   */
  value?: string
}

/** A colour field: a swatch, a hex entry and a picker popover. */
export default function ColorInput(given: ColorInputProps): JSX.Element {
  const props = mergeProps(
    { alpha: false, size: 'md', disabled: false, invalid: false } as Defaults<
      ColorInputProps,
      'alpha' | 'size' | 'disabled' | 'invalid'
    >,
    claimSlot(given),
  )
  return scope(() => {
    provide(IDENTITY, 'color-input')
    const borrowed: BorrowedHolder = {}
    provide(BORROWED, borrowed)
    const uid = createUniqueId()
    const hexField = elementRef<HTMLElement>()
    const root = elementRef<HTMLElement>()
    const mirror = createCell(null as string | null)
    const draft = createCell(null as string | null)
    const parseHex = createDerived(
      () => (text: string) =>
        ((bare: string) =>
          /^([0-9a-f]{3}|[0-9a-f]{6}|[0-9a-f]{8})$/i.test(bare)
            ? ((parsed) => (props.alpha ? parsed : parsed.withChannelValue('alpha', 1)))(
                zag.parse(`#${bare}`).toFormat('hsba'),
              )
            : null)(text.trim().replace(/^#/, '')),
    )
    const formatHex = createDerived(
      () => (shown: { toString: (format: 'hex' | 'hexa') => string }) =>
        shown.toString(props.alpha ? 'hexa' : 'hex').toLowerCase(),
    )
    const kept = createDerived(() =>
      mirror.value === null
        ? (parseHex.value(props.defaultValue ?? COLOR_INPUT_REST) ??
            parseHex.value(COLOR_INPUT_REST))!
        : zag.parse(mirror.value),
    )
    const controlled = createDerived(() =>
      props.value === undefined ? null : parseHex.value(props.value),
    )
    const color = createDerived(() =>
      controlled.value !== null && formatHex.value(controlled.value) !== formatHex.value(kept.value)
        ? controlled.value
        : kept.value,
    )
    const hex = createDerived(() => formatHex.value(color.value))
    const setColor = createDerived(
      () =>
        (next: {
          toFormat: (format: 'hsba') => { toString: (format: 'hsba' | 'hex' | 'hexa') => string }
        }) =>
          ((normalized) => (
            (mirror.value = normalized.toString('hsba')),
            props.onChange?.(formatHex.value(normalized))
          ))(next.toFormat('hsba')),
    )
    const commitDraft = createDerived(
      () => () =>
        draft.value !== null &&
        ((next) => ((draft.value = null), next !== null && setColor.value(next)))(
          parseHex.value(draft.value),
        ),
    )
    const toDraft = createDerived(
      () => (text: string) =>
        text
          .replace(/#/g, '')
          .trim()
          .slice(0, props.alpha ? 8 : 6),
    )
    const documentDirection = useDirection(() => root.value)
    const service = useMachine(
      zag.machine,
      () =>
        ({
          id: uid,
          dir: documentDirection(),
          value: color.value,
          format: 'hsba' as const,
          inline: true,
          disabled: props.disabled,
          onValueChange: (details) => {
            setColor.value(details.value)
          },
        }) as Partial<zag.Props>,
    )
    const api = createDerived(() => zag.connect(service, normalizeProps))
    const held = createDerived(() => (api.value.dragging ? service.context.get('activeId') : null))
    const fills = createDerived(() => ({
      hue: (
        api.value.getChannelSliderTrackProps({ channel: 'hue' }).style as {
          backgroundImage?: string
        }
      ).backgroundImage,
      alpha: (
        api.value.getChannelSliderTrackProps({ channel: 'alpha' }).style as {
          backgroundImage?: string
        }
      ).backgroundImage,
    }))
    const fromRange = createDerived(
      () => (channel: 'saturation' | 'brightness' | 'hue' | 'alpha', event: Event) =>
        api.value.setChannelValue(channel, Number((event.target as HTMLInputElement).value)),
    )
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const ran = agentMember({
        member: 'ColorInput',
        element: () => hexField.value?.querySelector('input'),
        state: () => ({ value: hex.value, disabled: props.disabled, invalid: props.invalid }),
        actions: {
          set: {
            argument: 'text',
            run: (value) =>
              (() => {
                const next = parseHex.value(value)
                if (next === null) throw new Error(`"${value}" is not a hex colour.`)
                draft.value = null
                setColor.value(next)
              })(),
          },
        },
        withholds: () => [root.value, borrowed.element?.()],
      })
      release1 = () => {
        ran()
      }
    }
    onMount(effect1)
    onCleanup(() => release1?.())
    return (
      <span
        class={styles.root}
        data-size={props.size}
        data-disabled={props.disabled ? '' : undefined}
        data-invalid={props.invalid ? '' : undefined}
        data-alpha={props.alpha ? '' : undefined}
        data-member="color-input"
        ref={root.attach}
      >
        <Popover
          label={props.pickerLabel}
          defaultOpen={props.defaultOpen}
          align="start"
          trigger={
            <button
              class={styles.swatch}
              type="button"
              disabled={props.disabled}
              aria-label={props.pickerLabel}
            >
              <span
                class={styles.swatchFill}
                style={{ '--pm-color-input-swatch': color.value.toString('css') }}
              />
            </button>
          }
        >
          {/* picker */}
          <div class={styles.picker}>
            {/* plane */}
            <div
              {...mergeParts(api.value.getAreaBackgroundProps(), api.value.getAreaProps(), {
                class: styles.plane,
              })}
            >
              <span
                {...mergeParts(api.value.getAreaThumbProps(), {
                  class: styles.thumb,
                  tabindex: undefined,
                  role: undefined,
                  'aria-label': undefined,
                  'aria-valuenow': undefined,
                  'aria-valuemin': undefined,
                  'aria-valuemax': undefined,
                  'aria-valuetext': undefined,
                  'aria-roledescription': undefined,
                  'aria-orientation': undefined,
                  'aria-disabled': undefined,
                  'data-state': held.value === 'area' ? 'dragging' : undefined,
                })}
              >
                <input
                  class={a11y.visuallyHidden}
                  type="range"
                  min={color.value.getChannelRange('saturation').minValue}
                  max={color.value.getChannelRange('saturation').maxValue}
                  step={color.value.getChannelRange('saturation').step}
                  value={color.value.getChannelValue('saturation')}
                  disabled={props.disabled}
                  aria-label={api.value.getAreaThumbProps()['aria-label']}
                  aria-valuetext={api.value.getAreaThumbProps()['aria-valuetext']}
                  oninput={($event: InputEvent) => fromRange.value('saturation', $event)}
                />
                <input
                  class={a11y.visuallyHidden}
                  type="range"
                  min={color.value.getChannelRange('brightness').minValue}
                  max={color.value.getChannelRange('brightness').maxValue}
                  step={color.value.getChannelRange('brightness').step}
                  value={color.value.getChannelValue('brightness')}
                  disabled={props.disabled}
                  tabindex="-1"
                  aria-hidden="true"
                  oninput={($event: InputEvent) => fromRange.value('brightness', $event)}
                />
              </span>
            </div>
            {/* rail */}
            <div
              {...mergeParts(api.value.getChannelSliderProps({ channel: 'hue' }), {
                class: styles.rail,
                'data-checker': undefined,
              })}
            >
              <span
                class={styles.railFill}
                style={{ 'background-image': fills.value.hue }}
                aria-hidden="true"
              />
              <span
                {...mergeParts(api.value.getChannelSliderThumbProps({ channel: 'hue' }), {
                  class: styles.thumb,
                  tabindex: undefined,
                  role: undefined,
                  'aria-label': undefined,
                  'aria-valuenow': undefined,
                  'aria-valuemin': undefined,
                  'aria-valuemax': undefined,
                  'aria-valuetext': undefined,
                  'aria-roledescription': undefined,
                  'aria-orientation': undefined,
                  'aria-disabled': undefined,
                  'data-state': held.value === 'hue' ? 'dragging' : undefined,
                })}
              >
                <input
                  class={a11y.visuallyHidden}
                  type="range"
                  min={color.value.getChannelRange('hue').minValue}
                  max={color.value.getChannelRange('hue').maxValue}
                  step={color.value.getChannelRange('hue').step}
                  value={color.value.getChannelValue('hue')}
                  disabled={props.disabled}
                  aria-label={
                    api.value.getChannelSliderThumbProps({ channel: 'hue' })['aria-label']
                  }
                  aria-valuetext={
                    api.value.getChannelSliderThumbProps({ channel: 'hue' })['aria-valuetext']
                  }
                  oninput={($event: InputEvent) => fromRange.value('hue', $event)}
                />
              </span>
            </div>
            {props.alpha ? (
              <div
                {...mergeParts(api.value.getChannelSliderProps({ channel: 'alpha' }), {
                  class: styles.rail,
                  'data-checker': '',
                })}
              >
                <span
                  class={styles.railFill}
                  style={{ 'background-image': fills.value.alpha }}
                  aria-hidden="true"
                />
                <span
                  {...mergeParts(api.value.getChannelSliderThumbProps({ channel: 'alpha' }), {
                    class: styles.thumb,
                    tabindex: undefined,
                    role: undefined,
                    'aria-label': undefined,
                    'aria-valuenow': undefined,
                    'aria-valuemin': undefined,
                    'aria-valuemax': undefined,
                    'aria-valuetext': undefined,
                    'aria-roledescription': undefined,
                    'aria-orientation': undefined,
                    'aria-disabled': undefined,
                    'data-state': held.value === 'alpha' ? 'dragging' : undefined,
                  })}
                >
                  <input
                    class={a11y.visuallyHidden}
                    type="range"
                    min={color.value.getChannelRange('alpha').minValue}
                    max={color.value.getChannelRange('alpha').maxValue}
                    step={color.value.getChannelRange('alpha').step}
                    value={color.value.getChannelValue('alpha')}
                    disabled={props.disabled}
                    aria-label={
                      api.value.getChannelSliderThumbProps({ channel: 'alpha' })['aria-label']
                    }
                    aria-valuetext={
                      api.value.getChannelSliderThumbProps({ channel: 'alpha' })['aria-valuetext']
                    }
                    oninput={($event: InputEvent) => fromRange.value('alpha', $event)}
                  />
                </span>
              </div>
            ) : null}
          </div>
        </Popover>
        <span
          class={styles.field}
          onkeydown={($event: KeyboardEvent) =>
            $event.key === 'Enter' && !composingKey($event) && commitDraft.value()
          }
          ref={hexField.attach}
        >
          <Input
            value={draft.value ?? hex.value.replace(/^#/, '')}
            prefix="#"
            size={props.size}
            disabled={props.disabled}
            invalid={props.invalid}
            id={props.id}
            autoComplete="off"
            aria-label={props['aria-label']}
            aria-labelledby={props['aria-labelledby']}
            aria-describedby={props['aria-describedby']}
            aria-required={props['aria-required']}
            onChange={($event) => (draft.value = toDraft.value($event))}
            onBlur={() => commitDraft.value()}
          />
        </span>
        {props.name !== undefined ? (
          <input type="hidden" name={props.name} value={hex.value} />
        ) : null}
      </span>
    )
  })
}
